    para_eer_degradation_ratio NUMBER,
    para_outdoor_heat_threshold NUMBER
)
AS
    TYPE num_list IS TABLE OF NUMBER;

    v_next_id NUMBER;
    v_cooling_kw NUMBER;
    v_heating_kw NUMBER;
    v_pre_energy NUMBER;
    v_usage_hours NUMBER;
    v_avg_indoor NUMBER;
    v_avg_outdoor NUMBER;
    v_total_output NUMBER;
    v_seasonal_eff NUMBER;
    v_avg_power_kw NUMBER;
    v_carnot NUMBER;
    v_phase_heat NUMBER;
    v_flow_rate NUMBER;
    v_required_flow NUMBER;
    v_emission_factor NUMBER;
    v_post_energy NUMBER;
    v_recomputed_eff NUMBER;
    v_recomputed_power_kw NUMBER;
    v_eer_threshold NUMBER;
    v_deleted_ids num_list;
    v_deleted_kwh num_list;
BEGIN
    SELECT NVL(MAX(id),0)+1 INTO v_next_id FROM carbon_emissions;

    FOR rec IN (SELECT * FROM air_conditioner_info ORDER BY ac_id FOR UPDATE) LOOP
        v_cooling_kw := rec.cooling_capacity_btu / 3412.0;
        v_heating_kw := rec.heating_capacity_btu / 3412.0;

        SELECT NVL(SUM(energy_consumption_kwh),0)
          INTO v_pre_energy
          FROM energy_consumption
         WHERE ac_id = rec.ac_id;

        SELECT NVL(SUM(usage_duration_hours),0)
          INTO v_usage_hours
          FROM usage_records
         WHERE ac_id = rec.ac_id;

        SELECT AVG(indoor_temperature_celsius),
               AVG(outdoor_temperature_celsius)
          INTO v_avg_indoor, v_avg_outdoor
          FROM usage_records
         WHERE ac_id = rec.ac_id;

        IF v_avg_indoor IS NULL THEN
            v_avg_indoor := 24.0;
        END IF;
        IF v_avg_outdoor IS NULL THEN
            v_avg_outdoor := 30.0;
        END IF;

        SELECT NVL(SUM(CASE WHEN mode = 'Cooling'
                            THEN v_cooling_kw * usage_duration_hours
                            ELSE v_heating_kw * usage_duration_hours
                       END), 0)
          INTO v_total_output
          FROM usage_records
         WHERE ac_id = rec.ac_id;

        IF v_pre_energy > 0 THEN
            v_seasonal_eff := v_total_output / v_pre_energy;
        ELSE
            v_seasonal_eff := rec.energy_efficiency_ratio;
        END IF;

        IF v_pre_energy > 0 AND v_usage_hours > 0 THEN
            v_avg_power_kw := v_pre_energy / v_usage_hours;
        ELSE
            v_avg_power_kw := rec.power_consumption_watts / 1000.0;
        END IF;

        IF v_avg_outdoor - v_avg_indoor > 0 THEN
            v_carnot := (v_avg_indoor + 273.15) /
                        (v_avg_outdoor - v_avg_indoor);
            IF v_seasonal_eff > v_carnot THEN
                v_seasonal_eff := v_carnot;
            END IF;
        END IF;

        SELECT NVL(MAX(phase_change_heat_kj_per_kg), 200)
          INTO v_phase_heat
          FROM refrigerant_properties
         WHERE refrigerant_type = rec.refrigerant_type;

        SELECT AVG(refrigerant_flow_rate_kg_per_s)
          INTO v_flow_rate
          FROM refrigerant_properties
         WHERE refrigerant_type = rec.refrigerant_type;

        IF v_flow_rate IS NULL THEN
            v_flow_rate := v_cooling_kw / 200.0;
        END IF;

        IF v_phase_heat > 0 THEN
            v_required_flow := v_cooling_kw / v_phase_heat;

            IF v_flow_rate < v_required_flow * para_flow_degradation_threshold THEN
                SELECT NVL(MAX(emission_factor), 0.5)
                  INTO v_emission_factor
                  FROM carbon_emissions;

                v_deleted_ids := num_list();
                v_deleted_kwh := num_list();

                SELECT energy_id, energy_consumption_kwh
                  BULK COLLECT INTO v_deleted_ids, v_deleted_kwh
                  FROM energy_consumption
